/**
 * Text-filtered single choice from a list (`design/components/combobox.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/combobox.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/combobox'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  useMediaQuery,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/controls/combobox.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import Skeleton from '../structure/Skeleton'

export type ComboboxFilter = NonNullable<ComboboxProps['filter']>

export interface ComboboxOption {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface ComboboxMessages {
  showOptions?: string
  clear?: string
  loadingOptions?: string
  options?: (count: number) => string
}

export interface ComboboxProps {
  /**
   * Keeps free text. Blur keeps the draft instead of restoring the selected label. A commit that
   * matches nothing sets the *selection* to `null` and keeps the text, which the app reads
   * through the controlled `inputValue` pair (React Aria's semantics, passed through). `name`
   * then serializes the typed text whenever no option is selected.
   */
  allowsCustomValue?: boolean
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Input's clear button. Clearing reports `onChange(null)`.
   */
  clearable?: boolean
  /**
   * Opens on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: string | null
  disabled?: boolean
  /**
   * Apps localize by passing it. An empty dropdown shows one line of text, not an illustration.
   */
  emptyMessage?: string
  filter?: false | 'contains' | 'startsWith'
  id?: string
  /**
   * The controlled input text, which async apps use to drive their queries.
   */
  inputValue?: string
  invalid?: boolean
  /**
   * Async loading state: skeleton rows in the panel and a spinning glyph in the field.
   */
  loading?: boolean
  /**
   * The member's strings. See `ComboboxMessages`.
   */
  messages?: ComboboxMessages
  /**
   * Serializes the *selected value*, not the typed text.
   */
  name?: string
  /**
   * For touched validation. Fires after the blur has been resolved: free text that matched
   * nothing is already `null`, and the input shows the selected label again. So a check on leave
   * reads the resolved value, never the abandoned draft.
   */
  onBlur?: (event: FocusEvent) => void
  onChange?: (value: string | null) => void
  onInputChange?: (value: string) => void
  /**
   * Requests the next page. Fires when the highlight reaches the last row or the open listbox is
   * scrolled to its end, while `loading` is false, at most once per `options` length. The app
   * appends the next page and sets `loading`, and the skeleton rows appear below the existing
   * rows. The highlight trigger is the primary one (WCAG 2.1.1), because keyboard navigation
   * cannot reach a scroll edge when the page fits the panel.
   */
  onLoadMore?: () => void
  /**
   * The *current* list. In async use, the app supplies a new list for each query.
   */
  options: ComboboxOption[]
  placeholder?: string
  /**
   * `'auto'` shows the popup as a sheet below `30rem` (the conventions' sheet presentation).
   * `'popover'` keeps the popover at every width. There is no always-sheet value, because the
   * closed union does not allow one (`docs/layout.md`).
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * Selection only by default. Free text that matches nothing resolves to `null` on blur, and
   * the input restores the selected label. `allowsCustomValue` below is the explicit opt-in, not
   * a hidden mode of this pair.
   */
  value?: string | null
}

/** Text-filtered single choice from a list. */
export default function Combobox(given: ComboboxProps): JSX.Element {
  const props = mergeProps(
    {
      allowsCustomValue: false,
      filter: 'contains',
      loading: false,
      emptyMessage: 'No results',
      clearable: false,
      size: 'md',
      disabled: false,
      invalid: false,
      presentation: 'auto',
    } as Defaults<
      ComboboxProps,
      | 'allowsCustomValue'
      | 'filter'
      | 'loading'
      | 'emptyMessage'
      | 'clearable'
      | 'size'
      | 'disabled'
      | 'invalid'
      | 'presentation'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const query = createCell(
      props.options.find((option) => option.value === (props.value ?? props.defaultValue))?.label ??
        '',
    )
    const showAll = createCell(false)
    const loadMoreAt = createCell(-1)
    const input = elementRef<HTMLElement>()
    const list = elementRef<HTMLElement>()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const sheetPanel = elementRef<HTMLElement>()
    const phone = useMediaQuery('phone')
    const sheeting = createDerived(() => props.presentation === 'auto' && phone())
    const say = createDerived(() => ({
      showOptions: 'Show options',
      clear: 'Clear',
      loadingOptions: 'Loading options…',
      options: (count: number) => `${count} options`,
      ...props.messages,
    }))
    const collator = createDerived(
      () => new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }),
    )
    const needle = createDerived(() => (props.inputValue ?? query.value).normalize('NFC'))
    const matches = createDerived(
      () => (label: string) =>
        ((text: string) =>
          needle.value === '' ||
          (props.filter === 'startsWith'
            ? collator.value.compare(text.slice(0, needle.value.length), needle.value) === 0
            : Array.from({ length: Math.max(0, text.length - needle.value.length + 1) }, (_, at) =>
                text.slice(at, at + needle.value.length),
              ).some((part) => collator.value.compare(part, needle.value) === 0)))(
          label.normalize('NFC'),
        ),
    )
    const shown = createDerived(() =>
      props.filter === false || showAll.value
        ? props.options
        : props.options.filter((option) => matches.value(option.label)),
    )
    const lastEnabled = createDerived(
      () => shown.value.findLast((option) => option.disabled !== true)?.value,
    )
    const requestMore = createDerived(
      () => () =>
        !props.loading &&
        loadMoreAt.value !== props.options.length &&
        ((loadMoreAt.value = props.options.length), props.onLoadMore?.(), true),
    )
    const emitBlur = createDerived(
      () => (event: FocusEvent) => setTimeout(() => props.onBlur?.(event)),
    )
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          collection: zag.collection({
            items: shown.value,
            itemToValue: (item) => item.value,
            itemToString: (item) => item.label,
            isItemDisabled: (item) => item.disabled === true,
          }),
          value: props.value === undefined ? undefined : props.value === null ? [] : [props.value],
          defaultValue: props.defaultValue == null ? undefined : [props.defaultValue],
          inputValue: props.inputValue,
          defaultOpen: props.defaultOpen,
          disabled: props.disabled,
          invalid: props.invalid,
          placeholder: props.placeholder,
          allowCustomValue: props.allowsCustomValue,
          inputBehavior: 'autohighlight' as const,
          positioning: { placement: 'bottom-start' as const, gutter: 2, sameWidth: false },
          ids: props.id === undefined ? undefined : { input: props.id },
          onPointerDownOutside: (event) =>
            panel.value?.contains(event.detail.originalEvent.target as Node) &&
            event.preventDefault(),
          onValueChange: (details) => {
            props.onChange?.(details.value[0] ?? null)
          },
          onInputValueChange: (details) => {
            void ((query.value = details.inputValue),
            details.reason === 'input-change' && (showAll.value = false),
            props.onInputChange?.(details.inputValue))
          },
          onOpenChange: (details) => {
            void ((showAll.value =
              details.open &&
              (details.reason === 'trigger-click' || details.reason === 'arrow-key')),
            !details.open && details.reason === 'escape-key' && revert.value())
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const revert = createDerived(
      () => () =>
        (props.allowsCustomValue && api.value.value.length === 0) ||
        api.value.setInputValue(
          props.options.find((option) => option.value === api.value.value[0])?.label ?? '',
        ),
    )
    const showClear = createDerived(
      () => props.clearable && api.value.inputValue !== '' && !props.disabled,
    )
    const showEmpty = createDerived(
      () => api.value.open && !props.loading && shown.value.length === 0,
    )
    const announcement = createDerived(() =>
      !api.value.open
        ? ''
        : props.loading
          ? say.value.loadingOptions
          : shown.value.length === 0
            ? props.emptyMessage
            : say.value.options(shown.value.length),
    )
    const formValue = createDerived(
      () => api.value.value[0] ?? (props.allowsCustomValue ? api.value.inputValue : ''),
    )
    const present = usePresence(
      () => api.value.open && !sheeting.value,
      () => panel.value,
    )
    const sheetPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => sheetPanel.value,
      'sheet.panel',
      { sheetSide: 'bottom' },
    )
    const scrimPresent = usePresence(
      () => api.value.open && sheeting.value,
      () => scrim.value,
      'dialog.scrim',
    )
    const effect1 = () => {
      void (
        api.value.open &&
        api.value.highlightedValue === null &&
        ((next) => next !== undefined && api.value.setHighlightValue(next))(
          api.value.value.find((chosen) => shown.value.some((option) => option.value === chosen)) ??
            shown.value.find((option) => option.disabled !== true)?.value,
        )
      )
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect1,
      true,
    )
    const effect2 = () => {
      void (
        api.value.open &&
        api.value.highlightedValue !== null &&
        api.value.highlightedValue === lastEnabled.value &&
        requestMore.value()
      )
    }
    watchEffect(
      createMemo(() => api.value.highlightedValue),
      effect2,
      true,
    )
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = agentMember({
        member: 'Combobox',
        element: () => input.value,
        state: () => ({
          value: api.value.value[0] ?? null,
          options: props.options.map((option) => ({
            id: option.value,
            label: option.label,
            ...(option.disabled === true ? { disabled: true } : {}),
          })),
          'input-value': api.value.inputValue,
          open: api.value.open,
          disabled: props.disabled,
          invalid: props.invalid,
        }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) =>
              (() => {
                if (api.value.value[0] === value) return
                api.value.setValue([value])
                api.value.setInputValue(
                  props.options.find((option) => option.value === value)?.label ?? '',
                )
              })(),
          },
          fill: { argument: 'text', run: (value) => api.value.setInputValue(value) },
          clear: () => (api.value.setValue([]), api.value.setInputValue('')),
          open: () => api.value.setOpen(true, 'trigger-click'),
          close: () => api.value.setOpen(false),
        },
      })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <>
        {/* field */}
        <div
          class={styles.field}
          id={api.value.getControlProps().id}
          data-size={props.size}
          data-state={api.value.open ? 'open' : 'closed'}
          data-disabled={props.disabled ? '' : undefined}
          data-invalid={props.invalid ? '' : undefined}
          data-loading={props.loading ? '' : undefined}
          data-sheeting={sheeting.value && api.value.open ? '' : undefined}
          data-member="combobox"
        >
          {/* trigger */}
          <input
            {...mergeParts(api.value.getInputProps(), {
              class: styles.input,
              name: undefined,
              required: undefined,
              'aria-label': props['aria-label'],
              'aria-labelledby': props['aria-labelledby'],
              'aria-describedby': props['aria-describedby'],
              'aria-required': props['aria-required'],
              onkeydown: ($event: KeyboardEvent) =>
                $event.key === 'Tab' &&
                api.value.open &&
                api.value.highlightedValue !== null &&
                api.value.selectValue(api.value.highlightedValue),
              onfocusout: ($event: FocusEvent) => emitBlur.value($event),
            })}
            ref={input.attach}
          />
          {props.name !== undefined ? (
            <input
              type="hidden"
              name={props.name}
              value={formValue.value}
              disabled={props.disabled || undefined}
            />
          ) : null}
          {showClear.value ? (
            <button
              class={styles.clear}
              type="button"
              aria-label={say.value.clear}
              onclick={() => (api.value.clearValue(), api.value.focus())}
            >
              <Icon name="clear" size={props.size} />
            </button>
          ) : null}
          {/* chevron */}
          <button
            {...mergeParts(api.value.getTriggerProps(), {
              class: styles.chevron,
              'aria-label': say.value.showOptions,
            })}
          >
            {props.loading ? (
              <span class={styles.spinner}>
                <Icon name="loading" size={props.size} />
              </span>
            ) : (
              <Icon name="expand" size={props.size} />
            )}
          </button>
          <div class={styles.status} role="status" aria-live="polite">
            {announcement.value}
          </div>
        </div>
        <Portal>
          {present() ? (
            <div {...mergeParts(api.value.getPositionerProps())}>
              {/* panel */}
              <div
                class={styles.content}
                style={{
                  '--radix-popover-trigger-width': 'var(--reference-width)',
                  '--radix-popover-content-available-height': 'var(--available-height)',
                  '--radix-popover-content-transform-origin': 'var(--transform-origin)',
                }}
                data-size={props.size}
                data-state={api.value.open ? 'open' : 'closed'}
                data-member="combobox"
                ref={panel.attach}
              >
                {/* list */}
                <ul
                  {...mergeParts(api.value.getContentProps(), {
                    class: styles.listbox,
                    hidden: undefined,
                    'aria-label': 'Suggestions',
                    'aria-labelledby':
                      props['aria-labelledby'] === undefined
                        ? undefined
                        : `${api.value.getContentProps().id} ${props['aria-labelledby']}`,
                    onscroll: () =>
                      (list.value?.scrollHeight ?? 0) -
                        (list.value?.scrollTop ?? 0) -
                        (list.value?.clientHeight ?? 0) <=
                        32 && requestMore.value(),
                  })}
                  ref={list.attach}
                >
                  <Each of={shown.value} by={(option) => option.value} renew>
                    {(option) => (
                      <li
                        {...mergeParts(api.value.getItemProps({ item: option }), {
                          class: styles.option,
                        })}
                      >
                        <span class={styles.check}>
                          {api.value.value.includes(option.value) ? (
                            <Icon name="confirm" size="sm" />
                          ) : null}
                        </span>
                        <span class={styles.text}>
                          <span class={styles.label}>{option.label}</span>
                          {option.description !== undefined ? (
                            <span class={styles.description}>{option.description}</span>
                          ) : null}
                        </span>
                      </li>
                    )}
                  </Each>
                </ul>
                {props.loading ? (
                  <div class={styles.rows} aria-hidden="true">
                    <Each of={[0, 1, 2]} by={(row) => row}>
                      {() => (
                        <div class={styles.row}>
                          <Skeleton textStep="sm" />
                        </div>
                      )}
                    </Each>
                  </div>
                ) : null}
                {showEmpty.value ? (
                  <div class={styles.empty} aria-hidden="true">
                    {props.emptyMessage}
                  </div>
                ) : null}
              </div>
            </div>
          ) : null}
          {scrimPresent() ? (
            <div
              class={sheet.scrim}
              data-state={api.value.open ? 'open' : 'closed'}
              ref={scrim.attach}
            />
          ) : null}
          {sheetPresent() ? (
            <div class={sheet.positioner}>
              <div
                class={sheet.panel}
                data-presentation="sheet"
                data-state={api.value.open ? 'open' : 'closed'}
                ref={sheetPanel.attach}
              >
                {/* panel */}
                <div
                  class={styles.sheetBody}
                  data-size={props.size}
                  data-member="combobox"
                  ref={panel.attach}
                >
                  {/* list */}
                  <ul
                    {...mergeParts(api.value.getContentProps(), {
                      class: styles.listbox,
                      hidden: undefined,
                      'aria-label': 'Suggestions',
                      'aria-labelledby':
                        props['aria-labelledby'] === undefined
                          ? undefined
                          : `${api.value.getContentProps().id} ${props['aria-labelledby']}`,
                      onscroll: () =>
                        (list.value?.scrollHeight ?? 0) -
                          (list.value?.scrollTop ?? 0) -
                          (list.value?.clientHeight ?? 0) <=
                          32 && requestMore.value(),
                    })}
                    ref={list.attach}
                  >
                    <Each of={shown.value} by={(option) => option.value} renew>
                      {(option) => (
                        <li
                          {...mergeParts(api.value.getItemProps({ item: option }), {
                            class: styles.option,
                          })}
                        >
                          <span class={styles.check}>
                            {api.value.value.includes(option.value) ? (
                              <Icon name="confirm" size="sm" />
                            ) : null}
                          </span>
                          <span class={styles.text}>
                            <span class={styles.label}>{option.label}</span>
                            {option.description !== undefined ? (
                              <span class={styles.description}>{option.description}</span>
                            ) : null}
                          </span>
                        </li>
                      )}
                    </Each>
                  </ul>
                  {props.loading ? (
                    <div class={styles.rows} aria-hidden="true">
                      <Each of={[0, 1, 2]} by={(row) => row}>
                        {() => (
                          <div class={styles.row}>
                            <Skeleton textStep="sm" />
                          </div>
                        )}
                      </Each>
                    </div>
                  ) : null}
                  {showEmpty.value ? (
                    <div class={styles.empty} aria-hidden="true">
                      {props.emptyMessage}
                    </div>
                  ) : null}
                </div>
              </div>
            </div>
          ) : null}
        </Portal>
      </>
    )
  })
}
